252	    PREPARING, // 상품 준비 중
253	    IN_WAREHOUSE, // 창고 보관 중
254	    SHIPMENT_STARTED, // 배송 시작
255	    IN_TRANSIT, // 배송 중
256	    COMPLETED, // 배송 완료
