260	    // 각 상태에서 전이 가능한 다음 상태들을 정의
261	    private static final Map<OrderStatus, Set<OrderStatus>> ALLOWED_TRANSITIONS = new HashMap<>();
262	
263	    static {
264	        // 상태 전이 규칙 초기화
265	        ALLOWED_TRANSITIONS.put(PENDING_PAYMENT, Set.of(PAYMENT_COMPLETED, COMPLETED, IN_WAREHOUSE));
266	        ALLOWED_TRANSITIONS.put(PAYMENT_COMPLETED, Set.of(PREPARING, REFUND_REQUESTED, IN_WAREHOUSE));
267	        ALLOWED_TRANSITIONS.put(PREPARING, Set.of(IN_WAREHOUSE, SHIPMENT_STARTED));
268	        ALLOWED_TRANSITIONS.put(IN_WAREHOUSE, Set.of(SHIPMENT_STARTED, COMPLETED));
269	        ALLOWED_TRANSITIONS.put(SHIPMENT_STARTED, Set.of(IN_TRANSIT));
270	        ALLOWED_TRANSITIONS.put(IN_TRANSIT, Set.of(COMPLETED));
271	        ALLOWED_TRANSITIONS.put(REFUND_REQUESTED, Set.of(REFUNDED));
272	        ALLOWED_TRANSITIONS.put(COMPLETED, Collections.emptySet());
273	        ALLOWED_TRANSITIONS.put(REFUNDED, Collections.emptySet());
274	    }
