249	public enum OrderStatus {
250	    PENDING_PAYMENT, // 결제 대기
251	    PAYMENT_COMPLETED, // 결제 완료
252	    PREPARING, // 상품 준비 중
253	    IN_WAREHOUSE, // 창고 보관 중
254	    SHIPMENT_STARTED, // 배송 시작
255	    IN_TRANSIT, // 배송 중
256	    COMPLETED, // 배송 완료
257	    REFUND_REQUESTED, // 환불 대기
258	    REFUNDED; // 환불 완료
259	
260	    // 각 상태에서 전이 가능한 다음 상태들을 정의
261	    private static final Map<OrderStatus, Set<OrderStatus>> ALLOWED_TRANSITIONS = new HashMap<>();
262	
263	    static {
264	        // 상태 전이 규칙 초기화
265	        ALLOWED_TRANSITIONS.put(PENDING_PAYMENT, Set.of(PAYMENT_COMPLETED, COMPLETED, IN_WAREHOUSE));
266	        ALLOWED_TRANSITIONS.put(PAYMENT_COMPLETED, Set.of(PREPARING, REFUND_REQUESTED, IN_WAREHOUSE));
267	        ALLOWED_TRANSITIONS.put(PREPARING, Set.of(IN_WAREHOUSE, SHIPMENT_STARTED));
268	        ALLOWED_TRANSITIONS.put(IN_WAREHOUSE, Set.of(SHIPMENT_STARTED, COMPLETED));
269	        ALLOWED_TRANSITIONS.put(SHIPMENT_STARTED, Set.of(IN_TRANSIT));
270	        ALLOWED_TRANSITIONS.put(IN_TRANSIT, Set.of(COMPLETED));
271	        ALLOWED_TRANSITIONS.put(REFUND_REQUESTED, Set.of(REFUNDED));
272	        ALLOWED_TRANSITIONS.put(COMPLETED, Collections.emptySet());
273	        ALLOWED_TRANSITIONS.put(REFUNDED, Collections.emptySet());
274	    }
275	
276	    /**
277	     * 현재 상태에서 새 상태로 전이가 가능한지 확인합니다.
278	     *
279	     * @param newStatus 전이하려는 새 상태
280	     * @return 전이 가능 여부
281	     */
282	    public boolean canTransitionTo(OrderStatus newStatus) {
283	        Set<OrderStatus> allowedNextStates = ALLOWED_TRANSITIONS.get(this);
284	        return allowedNextStates != null && allowedNextStates.contains(newStatus);
285	    }
286	
287	    /**
288	     * 현재 상태에서 전이 가능한 모든 상태를 반환합니다.
289	     *
290	     * @return 전이 가능한 상태 집합
291	     */
292	    public Set<OrderStatus> getAllowedNextStates() {
293	        return Collections.unmodifiableSet(ALLOWED_TRANSITIONS.getOrDefault(this, Collections.emptySet()));
294	    }
